// Picks the Xero organisation and works out which days this report covers.
// Tuesday to Friday: yesterday. Monday: Friday, Saturday and Sunday, so nothing falls between reports.
const s = $('Settings').first().json;
const tz = s.timezone || 'Asia/Singapore';
const orgs = $input.all().map(i => i.json).filter(o => o.tenantId && (!o.tenantType || o.tenantType === 'ORGANISATION'));
if (!orgs.length) throw new Error('No Xero organisation is connected to this Xero credential.');
const want = String(s.xeroOrganisation || '').trim().toLowerCase();
const org = want ? orgs.find(o => String(o.tenantName || '').trim().toLowerCase() === want) : orgs[0];
if (!org) throw new Error(`No connected Xero organisation is called "${s.xeroOrganisation}". Connected: ${orgs.map(o => o.tenantName).join(', ')}`);

const todayStr = /^\d{4}-\d{2}-\d{2}$/.test(String(s.reportDate || '')) ? s.reportDate
  : new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date());
const today = new Date(todayStr + 'T00:00:00Z');
const back = today.getUTCDay() === 1 ? 3 : 1;
const addDays = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; };
const from = addDays(today, -back), to = addDays(today, -1);
const iso = d => d.toISOString().slice(0, 10);
const xdt = d => `DateTime(${d.getUTCFullYear()}, ${String(d.getUTCMonth() + 1).padStart(2, '0')}, ${String(d.getUTCDate()).padStart(2, '0')})`;
const label = d => ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' +
  ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][d.getUTCMonth()];
return [{ json: {
  tenantId: org.tenantId,
  orgName: s.companyName || org.tenantName,
  today: todayStr,
  from: iso(from),
  to: iso(to),
  periodLabel: back === 1 ? label(from) : `${label(from)} to ${label(to)}`,
  whereRaised: `Type=="ACCREC" AND Date>=${xdt(from)} AND Date<${xdt(today)}`,
  wherePayments: `Date>=${xdt(from)} AND Date<${xdt(today)}`,
}}];

// Turns the three Xero pulls into six numbers and the five biggest overdue customers.
// Amounts in other currencies are converted with the rate Xero stored on the invoice or payment.
const s = $('Settings').first().json;
const d = $('Work out dates').first().json;
const base = String(s.baseCurrency || 'SGD').toUpperCase();
const rows = name => $(name).all().map(i => i.json).filter(j => j && Object.keys(j).length);
const toBase = (amount, currency, rate) => {
  const cur = String(currency || base).toUpperCase();
  const r = Number(rate);
  return cur === base || !(r > 0) ? Number(amount) || 0 : (Number(amount) || 0) / r;   // Xero rate = foreign units per 1 base unit
};
const xeroDay = (str, legacy) => {
  if (str) return String(str).slice(0, 10);
  const m = String(legacy || '').match(/\/Date\((\d+)/);
  return m ? new Date(parseInt(m[1], 10)).toISOString().slice(0, 10) : '';
};
const today = new Date(d.today + 'T00:00:00Z');
const r2 = n => Math.round(n * 100) / 100;
const money = n => base + ' ' + Number(n).toLocaleString('en-SG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const short = n => base + ' ' + Math.round(n).toLocaleString('en-SG');

// 1. Invoiced in the period (sales invoices dated in the period, approved or already paid)
const raised = rows('Get invoices raised').filter(i => i.Type === 'ACCREC' && ['AUTHORISED', 'PAID'].includes(i.Status));
const invoiced = raised.reduce((t, i) => t + toBase(i.Total, i.CurrencyCode, i.CurrencyRate), 0);
const invoicedExGst = raised.reduce((t, i) => t + toBase(i.SubTotal, i.CurrencyCode, i.CurrencyRate), 0);

// 2. Cash received in the period (customer payments only; supplier payments, refunds and deleted payments are left out)
const payments = rows('Get payments received').flatMap(p => p.Payments || [])
  .filter(p => p.PaymentType === 'ACCRECPAYMENT' && p.Status === 'AUTHORISED')
  .filter(p => { const day = xeroDay(null, p.Date); return !day || (day >= d.from && day <= d.to); });
const received = payments.reduce((t, p) => t + toBase(p.Amount, p.Invoice && p.Invoice.CurrencyCode, p.CurrencyRate), 0);

// 3-6. Overdue by age band, and who owes the most
const bands = [['1 to 30 days', 1, 30], ['31 to 60 days', 31, 60], ['61 to 90 days', 61, 90], ['over 90 days', 91, Infinity]];
const bandTotals = bands.map(() => 0);
const byCustomer = {};
let owedTotal = 0, overdueTotal = 0, overdueCount = 0;
for (const inv of rows('Get unpaid invoices')) {
  if (inv.Type && inv.Type !== 'ACCREC') continue;
  const due = Number(inv.AmountDue) || 0;
  if (!(due > 0)) continue;
  const amount = toBase(due, inv.CurrencyCode, inv.CurrencyRate);
  owedTotal += amount;
  const dueDay = xeroDay(inv.DueDateString, inv.DueDate);
  if (!dueDay) continue;
  const days = Math.round((today - new Date(dueDay + 'T00:00:00Z')) / 86400000);
  if (days < 1) continue;
  overdueTotal += amount; overdueCount++;
  bandTotals[bands.findIndex(([, lo, hi]) => days >= lo && days <= hi)] += amount;
  const name = (inv.Contact && inv.Contact.Name) || 'Unknown customer';
  const c = byCustomer[name] = byCustomer[name] || { name, amount: 0, invoices: 0, oldest: 0 };
  c.amount += amount; c.invoices++; c.oldest = Math.max(c.oldest, days);
}
const top = Object.values(byCustomer).sort((a, b) => b.amount - a.amount).slice(0, Number(s.topCustomers || 5));

const numbers = [
  { label: 'Invoiced', value: invoiced, note: `${raised.length} invoice${raised.length === 1 ? '' : 's'}, ${money(invoicedExGst)} before GST` },
  { label: 'Cash received', value: received, note: `${payments.length} customer payment${payments.length === 1 ? '' : 's'}` },
  ...bands.map(([label], k) => ({ label: 'Overdue ' + label, value: bandTotals[k], note: '' })),
];

const esc = t => String(t).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const cell = 'padding:8px 10px;border-bottom:1px solid #e6e4dc;font-size:14px';
const numRows = numbers.map((n, k) => `<tr${k === 2 ? ' style="border-top:2px solid #141c5c"' : ''}><td style="${cell}">${esc(n.label)}${n.note ? `<br><span style="color:#6b7092;font-size:12px">${esc(n.note)}</span>` : ''}</td><td style="${cell};text-align:right;font-weight:bold">${money(n.value)}</td></tr>`).join('');
const topRows = top.length ? top.map(c => `<tr><td style="${cell}">${esc(c.name)}</td><td style="${cell};text-align:right">${c.invoices}</td><td style="${cell};text-align:right">${c.oldest} days</td><td style="${cell};text-align:right;font-weight:bold">${money(c.amount)}</td></tr>`).join('')
  : `<tr><td style="${cell}" colspan="4">Nobody is overdue. Good morning indeed.</td></tr>`;
const html = `<div style="font-family:Arial,sans-serif;color:#141a3a;max-width:620px">
<p style="font-size:13px;color:#6b7092;margin:0">${esc(d.orgName)} · ${esc(d.periodLabel)}</p>
<h2 style="margin:4px 0 14px;color:#0e1440">Your numbers this morning</h2>
<table style="border-collapse:collapse;width:100%">${numRows}
<tr><td style="${cell};font-weight:bold">Total overdue (${overdueCount} invoices)</td><td style="${cell};text-align:right;font-weight:bold;color:#b3261e">${money(overdueTotal)}</td></tr>
<tr><td style="${cell};color:#6b7092">Total owed to you, including not yet due</td><td style="${cell};text-align:right;color:#6b7092">${money(owedTotal)}</td></tr></table>
<h3 style="margin:22px 0 6px;color:#0e1440">Biggest overdue customers</h3>
<table style="border-collapse:collapse;width:100%"><tr><th style="${cell};text-align:left">Customer</th><th style="${cell};text-align:right">Invoices</th><th style="${cell};text-align:right">Oldest</th><th style="${cell};text-align:right">Overdue</th></tr>${topRows}</table>
<p style="font-size:12px;color:#6b7092;margin-top:18px">Pulled from Xero on ${esc(d.today)}. Invoiced = sales invoices dated ${esc(d.periodLabel)}, including GST. Cash received = customer payments dated the same days. Other currencies converted at the rate Xero stored.</p></div>`;
const line = `${d.orgName}, ${d.periodLabel}: invoiced ${short(invoiced)}, cash in ${short(received)}, overdue ${short(overdueTotal)} (${short(bandTotals[3])} over 90 days)` +
  (top[0] ? `. Biggest: ${top[0].name} ${short(top[0].amount)}` : '');
return [{ json: {
  subject: `Daily numbers, ${d.periodLabel}: invoiced ${short(invoiced)}, cash in ${short(received)}, overdue ${short(overdueTotal)}`,
  html, line,
  invoiced: r2(invoiced), invoicedCount: raised.length, received: r2(received), paymentsCount: payments.length,
  overdue1to30: r2(bandTotals[0]), overdue31to60: r2(bandTotals[1]), overdue61to90: r2(bandTotals[2]), overdueOver90: r2(bandTotals[3]),
  overdueTotal: r2(overdueTotal), owedTotal: r2(owedTotal),
  topCustomers: top.map(c => ({ name: c.name, amount: r2(c.amount), invoices: c.invoices, oldestDays: c.oldest })),
}}];
